// Turn any Telegram message into ONE shape the rest of the workflow can rely on.
// Nothing downstream should ever read $json.message again - it reads this node instead.
const cfg = $('Config').first().json;
const msg = $('Telegram Trigger').first().json.message || {};

const VIDEO_HOSTS = [
  'instagram.com', 'instagr.am', 'youtube.com', 'youtu.be',
  'tiktok.com', 'vm.tiktok.com', 'facebook.com', 'fb.watch', 'x.com', 'twitter.com',
];

const text = (msg.text || msg.caption || '').trim();

// Telegram Bot API refuses to serve files bigger than 20 MB.
const TG_LIMIT = 20 * 1024 * 1024;

// A unique run id: message id + epoch + random. Two reels arriving at once cannot collide.
const runId = [
  msg.message_id || 0,
  Date.now(),
  Math.random().toString(36).slice(2, 8),
].join('-').replace(/[^A-Za-z0-9_-]/g, '');

const out = {
  run_id: runId,
  work_dir: cfg.work_root + '/' + runId,
  chat_id: (msg.chat && msg.chat.id) || null,
  message_id: msg.message_id || null,
  user_text: text,
  input_type: 'text',      // video | photo | link | text | error
  telegram_file_id: null,
  source_url: '',
  error_message: '',
};

// --- find a usable URL in the text, and refuse anything shell-unsafe -------------
// The URL is interpolated into a single-quoted shell argument for yt-dlp, so a
// single quote, backslash or whitespace would break out of the quoting. Reject those
// outright instead of trying to escape them.
const urlMatch = text.match(/https?:\/\/[^\s]+/i);
let url = urlMatch ? urlMatch[0].replace(/[).,]+$/, '') : '';
let urlHost = '';
let urlUnsafe = false;
if (url) {
  if (/['"\\\x60$;|&<>\s]/.test(url)) { urlUnsafe = true; }
  try { urlHost = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { url = ''; }
}
const isVideoLink = !!url && VIDEO_HOSTS.some((h) => urlHost === h || urlHost.endsWith('.' + h));

// --- decide the branch ----------------------------------------------------------
const videoPart =
  msg.video ||
  msg.animation ||
  (msg.document && /^video\//.test(msg.document.mime_type || '') ? msg.document : null) ||
  (msg.video_note || null);

if (videoPart) {
  out.input_type = 'video';
  out.telegram_file_id = videoPart.file_id;
  out.source_url = url || 'telegram:' + videoPart.file_id;
  if ((videoPart.file_size || 0) > TG_LIMIT) {
    out.input_type = 'error';
    out.error_message =
      'That video is ' + Math.round((videoPart.file_size || 0) / 1048576) + ' MB. Telegram bots can only ' +
      'download files up to 20 MB. Send the reel as a LINK instead and yt-dlp will fetch it.';
  }
} else if (Array.isArray(msg.photo) && msg.photo.length) {
  // photo is an array of sizes, last entry is the largest
  out.input_type = 'photo';
  out.telegram_file_id = msg.photo[msg.photo.length - 1].file_id;
  out.source_url = url || 'telegram-photo';
} else if (msg.document && /^image\//.test(msg.document.mime_type || '')) {
  out.input_type = 'photo';
  out.telegram_file_id = msg.document.file_id;
  out.source_url = url || 'telegram-photo';
} else if (urlUnsafe) {
  out.input_type = 'error';
  out.error_message = 'That link contains characters I will not pass to a shell (quote, backslash, ;, &, |, $). Send a plain URL.';
} else if (isVideoLink) {
  out.input_type = 'link';
  out.source_url = url;
} else if (text) {
  // plain text, or a URL that is not a known video host: still worth classifying
  out.input_type = 'text';
  out.source_url = url || '';
} else {
  out.input_type = 'error';
  out.error_message = 'I got a message with no video, no photo, no link and no text. Nothing to work with.';
}

if (!out.chat_id) {
  out.input_type = 'error';
  out.error_message = 'No chat id on that update - cannot reply. Check the trigger is set to "message".';
}

return [{ json: out }];

// Build ONE OpenAI-compatible chat/completions body: transcript + frames in a single call.
// Because the body is OpenAI-shaped, swapping provider = change the Header Auth credential
// + llm_base_url + llm_model in the Config node. Nothing here changes.
const cfg = $('Config').first().json;
const norm = $('Normalise Input').first().json;
const inp = $input.first().json;

const transcript = (inp.transcript || '').trim().slice(0, 6000);
const frames = (inp.frames_b64 || '')
  .split('\n')
  .map((s) => s.trim())
  .filter((s) => s.length > 100)     // drop blank / truncated lines
  .slice(0, Number(cfg.max_frames) || 8);

const SCHEMA = [
  '{',
  '  "category": "skill" | "todo" | "design" | "reference" | "discard",',
  '  "title": "short title, max 80 chars",',
  '  "summary": "2-4 sentences",',
  '  "key_points": ["..."],',
  '  "actions": ["imperative steps the owner should take, may be empty"],',
  '  "install_command": "exact command or repo URL if one is visible, else empty string",',
  '  "confidence": 0.0,',
  '  "tags": ["lowercase-kebab"],',
  '  "source_url": "...",',
  '  "needs_review": false',
  '}',
].join('\n');

const system = [
  'You triage short videos, screenshots and notes into a personal knowledge system.',
  'You receive an optional speech transcript, optional sampled video frames, and the text the owner typed.',
  '',
  'Categories:',
  '- "skill": describes a Claude Code skill/plugin/MCP server/CLI tool the owner could install or use.',
  '- "todo": an action the owner should take later (a technique to try, a procedure to run, a thing to buy/read).',
  '- "design": a fashion, brand, typography, UI or visual reference. Capture the VISUAL takeaways.',
  '- "reference": genuinely worth keeping but there is nothing to do with it.',
  '- "discard": noise, engagement bait, or nothing intelligible could be extracted.',
  '',
  'Rules:',
  '- Reply with ONE JSON object and nothing else. No markdown fences, no prose.',
  '- Never invent an install_command. If no command or repo URL is actually visible or spoken, use "".',
  '- confidence is your own honest 0-1 estimate that the category is right.',
  '- Set needs_review true if the input was too thin to judge, or the category was a coin flip.',
  '- If frames are present, read on-screen text out of them; many reels are visual-only.',
  '',
  'Exact shape:',
  SCHEMA,
].join('\n');

const userParts = [];
userParts.push({
  type: 'text',
  text: [
    'source_url: ' + (norm.source_url || '(none)'),
    'input_type: ' + norm.input_type,
    '',
    'owner typed:',
    norm.user_text || '(nothing)',
    '',
    'speech transcript (' + (transcript ? transcript.length + ' chars' : 'NO SPEECH DETECTED') + '):',
    transcript || '(silent, or speech could not be transcribed - rely on the frames)',
    '',
    frames.length
      ? frames.length + ' frames sampled from the video follow, in order.'
      : 'No frames available for this input.',
  ].join('\n'),
});
for (const b64 of frames) {
  userParts.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + b64 } });
}

const body = {
  model: cfg.llm_model,
  temperature: 0.2,
  max_tokens: 1200,
  response_format: { type: 'json_object' },   // JSON mode: Gemini / Groq / OpenRouter all honour this
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: userParts },
  ],
};

return [{ json: { body, frame_count: frames.length, transcript_chars: transcript.length } }];

// One job: turn whatever the provider returned into a trustworthy object, or say it failed.
// Handles: HTTP error, empty choices, markdown-fenced JSON, JSON with prose around it.
const norm = $('Normalise Input').first().json;
const res = $input.first().json || {};

const fail = (why, detail) => [{
  json: { parse_failed: true, failure_stage: 'classify', failure_reason: why, failure_detail: String(detail || '').slice(0, 600) },
}];

const status = res.statusCode;
const payload = res.body !== undefined ? res.body : res;

if (res.error && status === undefined) return fail('The LLM request never completed.', JSON.stringify(res.error));
if (typeof status === 'number' && (status < 200 || status >= 300)) {
  return fail('The LLM API returned HTTP ' + status + '.', typeof payload === 'string' ? payload : JSON.stringify(payload));
}

let raw = '';
try {
  raw = payload.choices[0].message.content;
  if (Array.isArray(raw)) raw = raw.map((p) => p.text || '').join('');
} catch (e) {
  return fail('The response had no choices[0].message.content.', JSON.stringify(payload));
}
if (!raw || !String(raw).trim()) return fail('The model returned an empty message.', JSON.stringify(payload).slice(0, 400));

// --- repair path: strip fences, then fall back to the widest {...} span ---------
let parsed = null;
const attempts = [];
attempts.push(String(raw).trim());
attempts.push(String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim());
const first = String(raw).indexOf('{');
const last = String(raw).lastIndexOf('}');
if (first !== -1 && last > first) attempts.push(String(raw).slice(first, last + 1));

for (const a of attempts) {
  try { const p = JSON.parse(a); if (p && typeof p === 'object') { parsed = p; break; } } catch (e) { /* next */ }
}
if (!parsed) return fail('The model did not return parseable JSON, even after repair.', raw);

// --- validate / coerce every field so downstream nodes cannot crash -------------
const ALLOWED = ['skill', 'todo', 'design', 'reference', 'discard'];
const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x)).filter(Boolean) : v ? [String(v)] : []);
const MIN_CONFIDENCE = Number($('Config').first().json.min_confidence) || 0.55;

let category = String(parsed.category || '').toLowerCase().trim();
let confidence = Number(parsed.confidence);
if (!isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

let needsReview = parsed.needs_review === true;
const notes = [];

if (!ALLOWED.includes(category)) {
  notes.push('model returned category "' + category + '", which is not one of ' + ALLOWED.join('/'));
  category = 'todo';
  needsReview = true;
}
if (confidence < MIN_CONFIDENCE && category !== 'discard') {
  notes.push('confidence ' + confidence.toFixed(2) + ' is below the ' + MIN_CONFIDENCE + ' bar');
  needsReview = true;
}
// Low confidence / flagged never guesses a destination: it lands in the to-do file flagged.
if (needsReview && category !== 'discard' && category !== 'todo') {
  notes.push('re-routed from "' + category + '" to todo for review');
  category = 'todo';
}

return [{
  json: {
    parse_failed: false,
    category,
    title: String(parsed.title || 'Untitled').slice(0, 120),
    summary: String(parsed.summary || '').slice(0, 2000),
    key_points: arr(parsed.key_points).slice(0, 12),
    actions: arr(parsed.actions).slice(0, 12),
    install_command: String(parsed.install_command || '').slice(0, 400),
    confidence,
    tags: arr(parsed.tags).map((t) => t.toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-|-$/g, '')).filter(Boolean).slice(0, 8),
    source_url: String(parsed.source_url || norm.source_url || ''),
    needs_review: needsReview,
    review_notes: notes,
    run_id: norm.run_id,
    input_type: norm.input_type,
    frame_count: $('Build LLM Request').first().json.frame_count,
    transcript_chars: $('Build LLM Request').first().json.transcript_chars,
  },
}];

