// Render the markdown that gets appended to the vault note.
// NOTE: model output is written to a FILE, never interpolated into a shell command.
// The only thing the git node interpolates is note_file, which comes from the four
// branch nodes above and is a fixed string I control.
const c = $input.first().json;
const norm = $('Normalise Input').first().json;

const stamp = new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC';
const bullets = (a) => (a.length ? a.map((x) => '- ' + x).join('\n') : '- (none given)');
const flag = c.needs_review ? ' #needs-review' : '';
const tags = c.tags.length ? c.tags.map((t) => '#' + t).join(' ') : '';

const L = [];
L.push('');
L.push('---');
L.push('');
L.push('## ' + c.title + flag);
L.push('');
L.push('- **captured:** ' + stamp + '  ·  **confidence:** ' + c.confidence.toFixed(2) + '  ·  **run:** `' + c.run_id + '`');
L.push('- **source:** ' + (c.source_url || '(sent straight to the bot, no URL)'));
if (tags) L.push('- **tags:** ' + tags);
if (c.review_notes && c.review_notes.length) L.push('- **why flagged:** ' + c.review_notes.join('; '));
L.push('');
L.push(c.summary || '(no summary)');
L.push('');

if (c.entry_kind === 'skill') {
  L.push('### What it claims to do');
  L.push(bullets(c.key_points));
  L.push('');
  L.push('### Install (paste this yourself - see below)');
  L.push('```bash');
  L.push(c.install_command || '# no install command was visible in the reel - open the source and find it');
  L.push('```');
  L.push('');
  L.push('### Verify it actually worked');
  L.push(bullets(c.actions.length ? c.actions : ['Run the command, then confirm the tool appears in claude plugin list or /help.', 'Use it once on a throwaway task before trusting it.']));
  L.push('');
  L.push('> [!warning] n8n cannot install this for you.');
  L.push('> The pipeline runs on the VPS; Claude Code runs on your laptop. This entry is a');
  L.push('> ready-to-paste command plus a check, nothing was installed anywhere.');
} else if (c.entry_kind === 'design') {
  L.push('### Visual takeaways');
  L.push(bullets(c.key_points));
  L.push('');
  L.push('### Could steal for');
  L.push(bullets(c.actions));
} else if (c.entry_kind === 'todo') {
  L.push('### Do');
  L.push(c.actions.length ? c.actions.map((x) => '- [ ] ' + x).join('\n') : '- [ ] decide what to do with this');
  L.push('');
  L.push('### Context');
  L.push(bullets(c.key_points));
} else {
  L.push('### Key points');
  L.push(bullets(c.key_points));
  if (c.actions.length) { L.push(''); L.push('### Possible follow-ups'); L.push(bullets(c.actions)); }
}
L.push('');

return [{
  json: {
    note_file: c.note_file,
    entry_kind: c.entry_kind,
    title: c.title,
    category: c.category,
    needs_review: c.needs_review,
    confidence: c.confidence,
    run_id: norm.run_id,
    entry_md: L.join('\n'),
  },
}];

