parameters.jsCode:
// Every failure path in the workflow lands here. Work out what broke from whatever
// fields are on the item, and write one plain-English Telegram message.
// Four inputs feed this node, so it must not assume any particular shape.
const norm = $('Normalise Input').first().json;
const j = $input.first().json || {};

const clip = (s, n = 500) => String(s == null ? '' : s).replace(/\s+$/,'').slice(0, n);
let headline = 'Something broke and I could not finish.';
let detail = '';
let hint = '';

// NOTE: read error_message off Normalise Input, not off $json. An Execute Command node
// REPLACES the item json with { exitCode, stdout, stderr }, so by the time the "error"
// branch of the Switch reaches here, the normalised fields are gone from $json.
if (norm.error_message) {
  // Normalise Input rejected the input up front
  headline = 'I cannot use what you sent.';
  detail = norm.error_message;
} else if (j.parse_failed) {
  headline = 'The classifier failed: ' + (j.failure_reason || 'unknown reason');
  detail = clip(j.failure_detail);
  hint = /HTTP 4[0-9][0-9]/.test(j.failure_reason || '')
    ? 'HTTP 4xx is usually a bad/expired API key or the wrong model name - check the Config node and the Header Auth credential.'
    : /HTTP 429/.test(j.failure_reason || '') ? 'Rate limited. Wait a minute and resend.'
    : 'Open the execution in n8n and look at the Classify node output.';
} else if (j.exitCode !== undefined && j.exitCode !== 0) {
  const out = clip(j.stderr) || clip(j.stdout);
  if (/yt-dlp|unavailable|private|login|rate|429|Unsupported URL/i.test(out) || norm.input_type === 'link') {
    headline = 'Download failed.';
    hint = 'Usually: the post is private or deleted, Instagram is rate-limiting the VPS, or the URL is not supported. '
      + 'If it is a private post, set ytdlp_extra in the Config node to --cookies /opt/n8n/cookies.txt.';
  } else {
    headline = 'Could not write the entry into the vault.';
    hint = 'The git step failed. Check the vault repo on the VPS: it may need a pull, or the deploy key expired.';
  }
  detail = out || 'exit code ' + j.exitCode + ' with no output';
} else if (j.error) {
  detail = clip(typeof j.error === 'string' ? j.error : JSON.stringify(j.error));
}

const lines = ['[x] ' + headline];
if (detail) lines.push('', detail);
if (hint) lines.push('', 'Likely fix: ' + hint);
lines.push('', 'run: ' + norm.run_id + '  (temp files have been cleaned up)');

return [{ json: { failure_text: lines.join('\n') } }];

parameters.command:
=D='{{ $('Normalise Input').item.json.work_dir }}'
case "$D" in
  {{ $('Config').item.json.work_root }}/?*) rm -rf -- "$D" ;;
  *) echo "refusing to delete unexpected path: $D" ;;
esac
exit 0
